function formatBrazilPhone(value: string): string {
  return formatSmartPhone(value)
}

function useStableCallback<T extends (...args: any[]) => any>(fn: T): T {
  const ref = useRef(fn)
  ref.current = fn
  return useCallback(((...args: any[]) => ref.current(...args)) as T, [])
}

