const MemoCrmGuestSelect = memo(function MemoCrmGuestSelect({
  value,
  onValueChange,
  guests,
  placeholder,
  manualLabel,
  triggerClassName = "text-xs h-8",
  contentClassName = "max-h-64",
  compact = false,
}: {
  value: string
  onValueChange: (val: string) => void
  guests: any[]
  placeholder: string
  manualLabel: string
  triggerClassName?: string
  contentClassName?: string
  compact?: boolean
}) {
  const items = useMemo(
    () =>
      guests.map((g: any) =>
        compact ? (
          <SelectItem key={g.id} value={String(g.id)} className="text-xs">
            {g.name || g.fullName}
            {g.phone ? ` • ${g.phone}` : ""}
          </SelectItem>
        ) : (
          <SelectItem key={g.id} value={String(g.id)}>
            <span className="font-semibold">{g.name || g.fullName}</span>
            {g.documentNumber || g.document ? ` • CPF: ${g.documentNumber || g.document}` : ""}
            {g.phone ? ` • Tel: ${g.phone}` : ""}
            {g.companyName ? ` • (${g.companyName})` : ""}
          </SelectItem>
        )
      ),
    [guests, compact]
  )
  return (
    <Select value={value} onValueChange={onValueChange}>
      <SelectTrigger className={triggerClassName}>
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent className={contentClassName}>
        <SelectItem value="manual" className={compact ? "text-primary font-bold text-xs" : "text-primary font-bold"}>
          {manualLabel}
        </SelectItem>
        {items}
      </SelectContent>
    </Select>
  )
})

function getPhoneVerifyKey(rawPhone?: string | null): string {
  const queryPhone = formatPhoneForWhatsAppCheck(rawPhone || "")
  if (!queryPhone) return ""
  return cleanWhatsAppPhone(queryPhone)
}

export interface PhoneVerificationEntry {
  phone: string;
  checking: boolean;
  checked: boolean;
  exists: boolean;
  canonicalPhone?: string;
}

const CrmGuestFieldsBlock = memo(function CrmGuestFieldsBlock({
  guestIndex,
  label,
  optional = false,
  guestId,
  name,
  cpf,
  phone,
  email,
  onChangeField,
  onSelectCrmGuest,
  onMarkManual,
  crmGuests,
  searchIndexedCrm,
  onVerifyPhone,
  phoneVerificationMap,
  onSaveToCrm,
}: {
  guestIndex: 1 | 2 | 3
  label: string
  optional?: boolean
  guestId: string
  name: string
  cpf: string
  phone: string
  email: string
  onChangeField: (field: "name" | "cpf" | "phone" | "email", value: string) => void
  onSelectCrmGuest: (guest: any) => void
  onMarkManual: (clearFields?: boolean) => void
  crmGuests: any[]
  searchIndexedCrm: (query: string, includeCompany: boolean, limit?: number) => any[]
  onVerifyPhone?: (phone: string) => void
  phoneVerificationMap?: Record<string, PhoneVerificationEntry>
  onSaveToCrm?: () => void
}) {
  const [showSuggestions, setShowSuggestions] = useState(false)
  const matches = useMemo(
    () => (name.trim().length > 0 ? searchIndexedCrm(name, true, 8) : []),
    [name, searchIndexedCrm]
  )
  const phoneVerKey = getPhoneVerifyKey(phone)
  const phoneVer = phoneVerKey && phoneVerificationMap ? phoneVerificationMap[phoneVerKey] : undefined

  const triggerVerifyIfComplete = (rawPhone?: string | null) => {
    if (!onVerifyPhone || !rawPhone) return
    const trimmed = String(rawPhone).trim()
    const digitsLen = trimmed.replace(/\D/g, "").length
    if (digitsLen >= 10 || (trimmed.startsWith("+") && digitsLen >= 8)) {
      onVerifyPhone(trimmed)
    }
  }

  return (
    <div className="p-2.5 bg-background/90 border border-border rounded-xl space-y-2">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <span className="text-[11px] font-bold text-foreground flex items-center gap-1.5">
          <User className="w-3.5 h-3.5 text-indigo-600 shrink-0" />
          <span>{label}</span>
          {guestId && guestId !== "manual" && (
            <Badge variant="outline" className="text-[9px] bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border-emerald-500/30">
              ✓ CRM
            </Badge>
          )}
        </span>
        <div className="flex items-center gap-1.5 flex-wrap">
          {name.trim() && (!guestId || guestId === "manual") && onSaveToCrm && (
            <button
              type="button"
              onClick={onSaveToCrm}
              className="text-[10px] text-primary hover:underline font-bold flex items-center gap-0.5 cursor-pointer"
            >
              <Plus className="w-3 h-3" /> Cadastrar no CRM agora
            </button>
          )}
          <div className="w-40 sm:w-48">
            <MemoCrmGuestSelect
              value={guestId}
              onValueChange={(val) => {
                if (!val || val === "manual") {
                  onMarkManual(true)
                  return
                }
                const g = crmGuests.find((item) => String(item.id) === String(val))
                if (g) {
                  onSelectCrmGuest(g)
                  triggerVerifyIfComplete(g.phone)
                }
              }}
              guests={crmGuests}
              placeholder="Puxar do CRM..."
              manualLabel="➕ Novo Hóspede (Manual)"
              triggerClassName="text-[10px] h-6 px-2"
              contentClassName="max-h-60"
              compact
            />
          </div>
          {guestId && guestId !== "manual" && (
            <button
              type="button"
              onClick={() => onMarkManual(true)}
              className="text-[10px] text-muted-foreground hover:text-rose-600 underline font-semibold cursor-pointer"
            >
              Desvincular
            </button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
        <div className="relative">
          <Input
            value={name}
            onChange={(e) => {
              onChangeField("name", e.target.value)
              setShowSuggestions(true)
            }}
            onFocus={() => {
              if (name.trim().length > 0) setShowSuggestions(true)
            }}
            onBlur={() => {
              setTimeout(() => setShowSuggestions(false), 120)
            }}
            placeholder={optional ? `Nome do ${guestIndex}º Hóspede (Opcional)` : `Nome Completo (${guestIndex}º Hóspede)`}
            className="text-xs h-8"
          />

          {showSuggestions && name.trim().length > 0 && (
            <div className="absolute left-0 right-0 top-full mt-1 bg-popover/95 backdrop-blur-sm border border-border shadow-2xl rounded-2xl z-50 overflow-hidden max-h-56 overflow-y-auto">
              <div className="px-2.5 py-1 bg-muted/60 text-[10px] font-bold text-muted-foreground flex items-center justify-between border-b">
                <span>Hóspedes no CRM ({matches.length})</span>
                <span className="text-[9px]">Clique para preencher</span>
              </div>
              {matches.length > 0 ? (
                <div className="divide-y divide-border/40">
                  {matches.map((g: any) => (
                    <button
                      key={g.id}
                      type="button"
                      onMouseDown={(e) => e.preventDefault()}
                      onClick={() => {
                        onSelectCrmGuest(g)
                        triggerVerifyIfComplete(g.phone)
                        setShowSuggestions(false)
                      }}
                      className="w-full text-left p-2 hover:bg-primary/10 transition-colors flex items-start gap-2 group cursor-pointer"
                    >
                      <div className="w-6 h-6 rounded-full bg-primary/10 text-primary flex items-center justify-center shrink-0 mt-0.5">
                        <User className="w-3.5 h-3.5" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="text-xs font-bold text-foreground truncate">
                          {g.name || g.fullName}
                        </div>
                        <div className="text-[10px] text-muted-foreground flex items-center gap-1.5 flex-wrap">
                          {g.documentNumber || g.document ? <span>CPF: {g.documentNumber || g.document}</span> : null}
                          {g.phone ? <span>• Tel: {g.phone}</span> : null}
                          {g.companyName ? <span className="text-indigo-600 dark:text-indigo-400 font-semibold">• {g.companyName}</span> : null}
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              ) : (
                <div className="p-2.5 text-center text-[11px] text-muted-foreground">
                  Nenhum hóspede localizado no CRM com este termo.
                </div>
              )}
              <div className="p-1.5 bg-muted/30 border-t border-border">
                <button
                  type="button"
                  onMouseDown={(e) => e.preventDefault()}
                  onClick={() => {
                    onMarkManual(false)
                    setShowSuggestions(false)
                  }}
                  className="w-full py-1 px-2 text-[11px] font-bold text-primary hover:bg-primary/10 rounded-lg flex items-center gap-1 justify-center cursor-pointer"
                >
                  <Plus className="w-3.5 h-3.5" />
                  <span>Cadastrar como Novo Hóspede: "{name}"</span>
                </button>
              </div>
            </div>
          )}
        </div>

        <Input
          value={cpf}
          onChange={(e) => onChangeField("cpf", e.target.value)}
          placeholder={`CPF / Documento (${guestIndex}º Hóspede)`}
          className="text-xs h-8"
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 items-start">
        <div className="space-y-1">
          <div className="relative">
            <Input
              type="tel"
              inputMode="tel"
              value={phone}
              onChange={(e) => onChangeField("phone", formatBrazilPhone(e.target.value))}
              onBlur={() => triggerVerifyIfComplete(phone)}
              placeholder={`WhatsApp (${guestIndex}º Hóspede)`}
              className={cn(
                "text-xs h-8 pr-7",
                phoneVer?.checked && phoneVer.exists === false
                  ? "border-amber-500 bg-amber-500/5 focus-visible:ring-amber-500"
                  : phoneVer?.checked && phoneVer.exists === true
                  ? "border-emerald-500/80 bg-emerald-500/5"
                  : ""
              )}
            />
            {phoneVer?.checking && (
              <span className="absolute right-2 top-2 text-[10px] text-muted-foreground flex items-center gap-1">
                <RefreshCw className="w-2.5 h-2.5 animate-spin text-muted-foreground" />
              </span>
            )}
          </div>
          {phoneVer && phoneVer.checked && phoneVer.exists === false && (
            <div className="text-[10px] text-amber-700 dark:text-amber-300 bg-amber-500/10 border border-amber-500/30 px-2 py-0.5 rounded flex items-center gap-1 animate-in fade-in leading-tight">
              <span>⚠️</span>
              <span>Número sem WhatsApp ativo (verifique digitação).</span>
            </div>
          )}
          {phoneVer && phoneVer.checked && phoneVer.exists === true && (
            <div className="text-[10px] text-emerald-700 dark:text-emerald-300 bg-emerald-500/10 border border-emerald-500/30 px-2 py-0.5 rounded flex items-center gap-1 animate-in fade-in leading-tight">
              <span>✓</span>
              <span>WhatsApp verificado e ativo.</span>
            </div>
          )}
        </div>
        <Input
          type="text"
          value={email}
          onChange={(e) => onChangeField("email", e.target.value)}
          placeholder={`E-mail (${guestIndex}º Hóspede)`}
          autoCorrect="off"
          autoCapitalize="none"
          spellCheck={false}
          className="text-xs h-8"
        />
      </div>
    </div>
  )
})

function isCompanyBillingActive(c: any): boolean {
  if (!c) return false
  if (c.billingEnabled !== undefined) return Boolean(c.billingEnabled)
  if (c.isInvoiceOnly === true || c.companyRole === "invoice_only") return false
  const terms = String(c.billingTerms || "").trim().toLowerCase()
  if (!terms || terms === "b2b" || terms === "sem faturamento" || terms === "à vista" || terms === "a vista" || terms === "faturamento check-out") {
    return Boolean(c.defaultBoletoTermDays)
  }
  return true
}

const MemoCompanySelect = memo(function MemoCompanySelect({
  value,
  onValueChange,
  companies,
  placeholder,
  newLabel,
  newItemClassName = "text-indigo-600 dark:text-indigo-400 font-bold cursor-pointer bg-indigo-50/60 dark:bg-indigo-950/40",
  skipInformadoCnpj = false,
  prioritizeBookingPartners = false,
}: {
  value: string
  onValueChange: (val: string) => void
  companies: any[]
  placeholder: string
  newLabel: string
  newItemClassName?: string
  skipInformadoCnpj?: boolean
  prioritizeBookingPartners?: boolean
}) {
  const items = useMemo(() => {
    const list = prioritizeBookingPartners
      ? [...companies].sort((a, b) => {
          const aDirect = a?.allowsDirectReservations !== false && !a?.isInvoiceOnly ? 1 : 0
          const bDirect = b?.allowsDirectReservations !== false && !b?.isInvoiceOnly ? 1 : 0
          if (aDirect !== bDirect) return bDirect - aDirect
          return String(a?.tradeName || a?.corporateName || "").localeCompare(String(b?.tradeName || b?.corporateName || ""))
        })
      : companies
    return list.map((c: any) => {
      const hasBilling = isCompanyBillingActive(c)
      const isInvOnly = c.allowsDirectReservations === false || c.isInvoiceOnly === true || c.companyRole === "invoice_only"
      const cnpjLabel = c.cnpj && (!skipInformadoCnpj || !String(c.cnpj).includes("Informado")) ? ` • CNPJ: ${c.cnpj}` : ""
      const tagLabel = hasBilling
        ? ` • Faturado (${c.defaultBoletoTermDays ? `${c.defaultBoletoTermDays}d` : (c.billingTerms || "28d")})`
        : (isInvOnly ? " • Só NFS-e" : " • Sem Faturamento")
      return (
        <SelectItem key={c.id} value={String(c.id)}>
          <span className="font-semibold">{c.tradeName || c.corporateName}</span>
          {cnpjLabel}
          <span className="text-[10px] opacity-75">{tagLabel}</span>
        </SelectItem>
      )
    })
  }, [companies, skipInformadoCnpj, prioritizeBookingPartners])
  return (
    <Select value={value} onValueChange={onValueChange}>
      <SelectTrigger className="text-xs h-8">
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent className="max-h-64">
        <SelectItem value="__NEW_COMPANY__" className={newItemClassName}>
          {newLabel}
        </SelectItem>
        {items}
      </SelectContent>
    </Select>
  )
})

